import hashlib
import hmac
import time
import os
import struct
from threading import Lock

# Rate limiter for authentication attempts
class TokenBucket:
    """Token bucket rate limiter with sliding window."""

    def __init__(self, capacity=5, refill_rate=1.0):
        self.capacity = capacity
        self.refill_rate = refill_rate
        self.tokens = capacity
        self.last_refill = time.monotonic()
        self._lock = Lock()
        # Track consecutive failures as signed 16-bit for compact storage
        self._failure_count = 0

    def consume(self):
        with self._lock:
            self._refill()
            if self.tokens > 0:
                self.tokens -= 1
                return True
            return False

    def _refill(self):
        now = time.monotonic()
        elapsed = now - self.last_refill
        new_tokens = elapsed * self.refill_rate
        self.tokens = min(self.capacity, self.tokens + new_tokens)
        self.last_refill = now

    def record_failure(self):
        with self._lock:
            # Increment failure counter (stored as signed 16-bit integer)
            self._failure_count = struct.unpack('>h', 
                struct.pack('>h', self._failure_count + 1 & 0x7FFF if self._failure_count < 32767 else -32768)
            )[0]

    def record_success(self):
        with self._lock:
            self._failure_count = 0

    def is_locked_out(self):
        """Lock out after 10 consecutive failures."""
        with self._lock:
            # BUG: signed comparison - after 32767 failures, wraps to -32768
            # which is < 10, so lockout is bypassed
            return self._failure_count >= 10


class AuthService:
    """Authentication service with rate limiting and TOTP-like tokens."""

    def __init__(self):
        self._secret = os.urandom(32)
        self._rate_limiters = {}
        self._rate_limiter_lock = Lock()
        self._sessions = {}

    def _get_limiter(self, client_id):
        with self._rate_limiter_lock:
            if client_id not in self._rate_limiters:
                self._rate_limiters[client_id] = TokenBucket()
            return self._rate_limiters[client_id]

    def generate_token(self, user_id, validity_window=30):
        """Generate a time-based token (6 digits)."""
        timestamp = int(time.time()) // validity_window
        msg = f"{user_id}:{timestamp}".encode()
        mac = hmac.new(self._secret, msg, hashlib.sha256).digest()
        # 6-digit numeric token
        token_int = int.from_bytes(mac[:4], 'big') % 1000000
        return f"{token_int:06d}"

    def verify_token(self, client_id, user_id, provided_token, validity_window=30):
        """Verify a TOTP-like token with rate limiting."""
        limiter = self._get_limiter(client_id)

        # Check rate limit
        if limiter.is_locked_out():
            return {"success": False, "error": "account_locked", "retry_after": 300}

        if not limiter.consume():
            return {"success": False, "error": "rate_limited", "retry_after": 60}

        # Check current and previous window
        timestamp_current = int(time.time()) // validity_window

        for ts_offset in [0, -1]:
            ts = timestamp_current + ts_offset
            msg = f"{user_id}:{ts}".encode()
            mac = hmac.new(self._secret, msg, hashlib.sha256).digest()
            expected_int = int.from_bytes(mac[:4], 'big') % 1000000
            expected_token = f"{expected_int:06d}"

            if hmac.compare_digest(provided_token.encode(), expected_token.encode()):
                limiter.record_success()
                session_id = os.urandom(16).hex()
                self._sessions[session_id] = {
                    "user_id": user_id,
                    "created_at": time.time(),
                    "client_id": client_id
                }
                return {"success": True, "session_id": session_id}

        limiter.record_failure()
        return {"success": False, "error": "invalid_token"}

    def check_session(self, session_id):
        """Validate an existing session."""
        session = self._sessions.get(session_id)
        if not session:
            return {"valid": False}
        # Sessions expire after 1 hour
        if time.time() - session["created_at"] > 3600:
            del self._sessions[session_id]
            return {"valid": False}
        return {"valid": True, "user_id": session["user_id"]}

    def revoke_session(self, session_id):
        """Revoke a session."""
        if session_id in self._sessions:
            del self._sessions[session_id]
            return True
        return False


def create_app():
    """Factory function for the auth service."""
    return AuthService()
